static SDL_Window *window=NULL; static SDL_Renderer *renderer=NULL; static SDL_Texture *logo_texture=NULL,*background_texture=NULL,*cover_texture=NULL; static TTF_Font *font=NULL;
#define INPUT_COOLDOWN_MS 200
